-- ============================================================================
-- Dev/admin bootstrap: provision a super_admin for one tenant.
--
-- Safe to rerun. Idempotent.
-- Runs in Supabase SQL Editor (single DO block, no \set).
--
-- TODO(production): Replace this manual seed with one of:
--   (a) an auth.users INSERT trigger that creates central_users + a default
--       tenant_membership,
--   (b) a SECURITY DEFINER RPC (e.g. public.bootstrap_self()) called from
--       the client after sign-in,
--   (c) a service-role Edge Function invoked from an invite/onboarding flow.
-- Browser code MUST NOT write to central_users, tenant_memberships,
-- user_roles, workspaces, or object_memberships.
-- ============================================================================

DO $$
DECLARE
  -- ---- Inputs (edit these) ---------------------------------------------------
  v_auth_email     text := 'dev-superadmin@xcamp.local';
  v_tenant_slug    text := 'xcamp-dev';
  v_tenant_name    text := 'Xcamp-dev';
  v_workspace_slug text := 'default';
  v_workspace_name text := 'Default workspace';

  -- ---- Resolved --------------------------------------------------------------
  v_auth_user_id   uuid;
  v_tenant_id      uuid;
  v_central_id     uuid;
  v_workspace_id   uuid;
  v_role_exists    boolean;
BEGIN
  -- 0. Verify the enum value exists before we try to use it.
  SELECT EXISTS (
    SELECT 1
    FROM pg_type t
    JOIN pg_enum e ON e.enumtypid = t.oid
    WHERE t.typname = 'app_role'
      AND e.enumlabel = 'super_admin'
  ) INTO v_role_exists;

  IF NOT v_role_exists THEN
    RAISE EXCEPTION
      'Enum public.app_role has no value ''super_admin''. Add it before running this seed, or pick another role.';
  END IF;

  -- 1. Resolve the auth user.
  SELECT id INTO v_auth_user_id
  FROM auth.users
  WHERE email = v_auth_email;

  IF v_auth_user_id IS NULL THEN
    RAISE EXCEPTION 'No auth.users row for email %', v_auth_email;
  END IF;

  -- 2. Ensure tenant.
  SELECT id INTO v_tenant_id
  FROM public.tenants
  WHERE slug = v_tenant_slug;

  IF v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (slug, name, status)
    VALUES (v_tenant_slug, v_tenant_name, 'active')
    RETURNING id INTO v_tenant_id;
  END IF;

  -- 3. Ensure central_users (PK = auth.uid()).
  INSERT INTO public.central_users (id, email, tenant_id)
  VALUES (v_auth_user_id, v_auth_email, v_tenant_id)
  ON CONFLICT (id) DO UPDATE
    SET email      = EXCLUDED.email,
        updated_at = now();

  SELECT id INTO v_central_id
  FROM public.central_users
  WHERE id = v_auth_user_id;

  -- 4. Ensure tenant_membership (access).
  INSERT INTO public.tenant_memberships
    (tenant_id, user_id, role, status, joined_at)
  VALUES
    (v_tenant_id, v_auth_user_id, 'super_admin', 'active', now())
  ON CONFLICT (tenant_id, user_id) DO UPDATE
    SET role      = EXCLUDED.role,
        status    = 'active',
        joined_at = COALESCE(public.tenant_memberships.joined_at, now());

  -- 5. Ensure user_roles (authority) — tenant-scoped only.
  --    The unique constraint is (user_id, role, tenant_id); a NULL tenant_id
  --    would not deduplicate reliably and is not required by the app.
  INSERT INTO public.user_roles (user_id, role, tenant_id)
  VALUES (v_auth_user_id, 'super_admin'::public.app_role, v_tenant_id)
  ON CONFLICT (user_id, role, tenant_id) DO NOTHING;

  -- 6. Ensure at least one workspace exists for this tenant.
  SELECT id INTO v_workspace_id
  FROM public.workspaces
  WHERE tenant_id = v_tenant_id
    AND slug = v_workspace_slug
    AND deleted_at IS NULL;

  IF v_workspace_id IS NULL THEN
    INSERT INTO public.workspaces
      (tenant_id, name, slug, created_by, is_active)
    VALUES
      (v_tenant_id, v_workspace_name, v_workspace_slug, v_central_id, true)
    ON CONFLICT (slug, tenant_id) DO NOTHING
    RETURNING id INTO v_workspace_id;

    IF v_workspace_id IS NULL THEN
      SELECT id INTO v_workspace_id
      FROM public.workspaces
      WHERE tenant_id = v_tenant_id AND slug = v_workspace_slug;
    END IF;
  END IF;

  -- 7. object_memberships for the workspace (owner). Optional but cheap.
  INSERT INTO public.object_memberships
    (object_type, object_id, user_central_id, role, status, joined_at, tenant_id)
  VALUES
    ('workspace', v_workspace_id, v_central_id, 'owner', 'active', now(), v_tenant_id)
  ON CONFLICT (user_central_id, object_id, object_type) DO NOTHING;

  RAISE NOTICE 'Bootstrap OK: auth=% central=% tenant=% workspace=%',
    v_auth_user_id, v_central_id, v_tenant_id, v_workspace_id;
END
$$;

-- ---------------- Validation (read-only) ----------------
SELECT 'central_users' AS table, id, email, tenant_id FROM public.central_users
  WHERE email = 'dev-superadmin@xcamp.local';

SELECT 'tenant_memberships' AS table, tenant_id, user_id, role, status
  FROM public.tenant_memberships
  WHERE user_id = (SELECT id FROM auth.users WHERE email = 'dev-superadmin@xcamp.local');

SELECT 'user_roles' AS table, user_id, role, tenant_id
  FROM public.user_roles
  WHERE user_id = (SELECT id FROM auth.users WHERE email = 'dev-superadmin@xcamp.local');

SELECT 'workspaces' AS table, id, tenant_id, slug, name, is_active
  FROM public.workspaces
  WHERE tenant_id = (SELECT id FROM public.tenants WHERE slug = 'xcamp-dev');
